// ============================================================
// RJ Saúde — CHAMADA ONLINE (P-37) — versão com o DESIGN oficial
// Painel de chamada de senhas que roda pela INTERNET (Render/nuvem).
// Node.js puro, SEM dependências. Telas: /totem  /painel  /recepcao
// Tempo real via SSE. Estado em memória. Zera a numeração por dia (24h).
// ============================================================
'use strict';
const http = require('http');
const PORT = process.env.PORT || 8080;

// ---- Configuração (clínica, serviços, guichês, voz) ----
const config = {
  clinica: { nome:'RJ Saúde', subtitulo:'Medicina Ocupacional',
             cor_primaria:'#0E5C3F', cor_secundaria:'#1F8A5B', cor_destaque:'#C9A24B',
             logo:'/assets/logo.png' },
  voz: { ativa:true, idioma:'pt-BR', velocidade:0.95, repeticoes:1, gongo:true },
  servicos: [
    { id:'comum',       nome:'Comum',                       prefixo:'C', icone:'user',   preferencial:false },
    { id:'prioritaria', nome:'Prioritária',                 prefixo:'P', icone:'access', preferencial:true  },
    { id:'laboratorio', nome:'Laboratório / Toxicológico',  prefixo:'L', icone:'flask',  preferencial:false }
  ],
  locais: [ { id:'g1', nome:'Guichê 1' }, { id:'g2', nome:'Guichê 2' } ],
  mostrar_nome_paciente: true,
  impressao: { ativa:true, largura_mm:58 }
};

// ---- Assets embutidos (base64) ----
const ASSETS = {
  TOTEM:    "",
  PAINEL:   "",
  RECEPCAO: "",
  ICONES:   "",
  ESTILO:   "",
  LOGO:     ""
};
const dec = b => Buffer.from(b, 'base64');
const decs = b => dec(b).toString('utf8');

// ---- Fila de senhas (em memória) + zera por dia ----
class Fila {
  constructor(cfg){ this.config=cfg; this.contadores={}; this.emitidas=[]; this.chamadas=[]; this.data=this._hoje(); }
  _hoje(){ const d=new Date(); return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }
  _verificarDia(){ const h=this._hoje(); if(h!==this.data){ this.contadores={}; this.emitidas=[]; this.chamadas=[]; this.data=h; } }
  emitir(servicoId){
    this._verificarDia();
    const s=this.config.servicos.find(x=>x.id===servicoId);
    if(!s) throw new Error('Serviço inválido: '+servicoId);
    const n=(this.contadores[s.prefixo]||0)+1; this.contadores[s.prefixo]=n;
    const senha=s.prefixo+'-'+String(n).padStart(3,'0');
    const reg={ senha, servico:s.id, servicoNome:s.nome, preferencial:!!s.preferencial, emitidaEm:new Date().toISOString() };
    this.emitidas.push(reg); return reg;
  }
  chamar({ senha, nome, local, origem }){
    this._verificarDia();
    const idx=this.emitidas.findIndex(e=>e.senha===senha);
    const base=idx>=0?this.emitidas.splice(idx,1)[0]:{};
    const reg={ senha:senha||base.senha||'', nome:nome||base.nome||'', servicoNome:base.servicoNome||'',
                local:local||'', origem:origem||'recepcao', chamadaEm:new Date().toISOString() };
    this.chamadas.unshift(reg); this.chamadas=this.chamadas.slice(0,50); return reg;
  }
  estado(){ this._verificarDia(); return { emitidas:this.emitidas, chamadas:this.chamadas, ultimaChamada:this.chamadas[0]||null }; }
}
const fila = new Fila(config);

// ---- SSE (TV + recepção) ----
const clientes = new Set();
function transmitir(evento, dados){
  const carga='event: '+evento+'\ndata: '+JSON.stringify(dados)+'\n\n';
  for(const res of clientes){ try{ res.write(carga); }catch(e){} }
}
function emitirSenha(id){ const r=fila.emitir(id); transmitir('senha_emitida', r); return r; }
function registrarChamada(d){ const r=fila.chamar(d); transmitir('senha_chamada', Object.assign({}, r, { voz:config.voz, mostrarNome:config.mostrar_nome_paciente })); return r; }

// ---- helpers HTTP ----
function json(res,obj,st){ res.writeHead(st||200,{'Content-Type':'application/json; charset=utf-8'}); res.end(JSON.stringify(obj)); }
function corpo(req){ return new Promise(r=>{ let b=''; req.on('data',c=>b+=c); req.on('end',()=>{ try{ r(b?JSON.parse(b):{}); }catch(e){ r({}); } }); }); }
function pagina(res,b64html){ res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'}); res.end(decs(b64html)); }

const servidor = http.createServer(async (req,res)=>{
  const u=new URL(req.url,'http://'+req.headers.host); const rota=u.pathname;

  // API
  if(rota==='/api/config') return json(res,{ clinica:config.clinica, servicos:config.servicos, locais:config.locais,
    mostrarNome:config.mostrar_nome_paciente, voz:config.voz, impressao:config.impressao });
  if(rota==='/api/estado') return json(res, fila.estado());
  if(rota==='/api/senha' && req.method==='POST'){ const b=await corpo(req);
    try{ return json(res, emitirSenha(b.servico)); }catch(e){ return json(res,{erro:e.message},400); } }
  if(rota==='/api/chamar' && req.method==='POST'){ const b=await corpo(req);
    return json(res, registrarChamada(Object.assign({}, b, { origem:'recepcao' }))); }

  // SSE
  if(rota==='/events'){
    res.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-cache','Connection':'keep-alive'});
    res.write('event: estado\ndata: '+JSON.stringify(fila.estado())+'\n\n');
    clientes.add(res);
    const ping=setInterval(()=>{ try{ res.write(': ping\n\n'); }catch(e){} },20000);
    req.on('close',()=>{ clearInterval(ping); clientes.delete(res); });
    return;
  }

  // Assets
  if(rota==='/assets/logo.png'){ res.writeHead(200,{'Content-Type':'image/png'}); return res.end(dec(ASSETS.LOGO)); }
  if(rota==='/assets/icones.js'){ res.writeHead(200,{'Content-Type':'text/javascript; charset=utf-8'}); return res.end(decs(ASSETS.ICONES)); }
  if(rota==='/assets/estilo.css'){ res.writeHead(200,{'Content-Type':'text/css; charset=utf-8'}); return res.end(decs(ASSETS.ESTILO)); }

  // Páginas
  if(rota==='/' || rota==='/totem')    return pagina(res, ASSETS.TOTEM);
  if(rota==='/painel' || rota==='/tv') return pagina(res, ASSETS.PAINEL);
  if(rota==='/recepcao')               return pagina(res, ASSETS.RECEPCAO);

  res.writeHead(404); res.end('404');
});

servidor.listen(PORT, ()=>{ console.log('RJ Saude - Chamada Online (design oficial) rodando na porta '+PORT); });
